$hook_archive = @'
#!/usr/bin/env bash
# session-archive.sh -- Claude Code SessionEnd hook (thin shim)
# Passes the raw hook stdin to ait-harvest.py `archive`, which copies the
# transcript (+ subagents) to the dotprofile and commits/pushes. All logic and
# logging live in the Python helper (~/.aitools/logs/ait-harvest.log).
#
# Design (plan imperative-gliding-newell.md §4 + §20.2 C3):
#   - Standalone (no aitools-lib); bash-only on all platforms.
#   - Raw stdin -> python (no bash JSON parsing; the helper parses robustly).
#   - Always exit 0 (a hook must never break Claude Code).
#   - If Python / the helper is missing or the helper exits non-zero, append a
#     one-line reason to ~/.aitools/logs/session-archive.log FROM BASH -- because
#     Python may be the missing thing, or may die before its logging initializes.
#
# Baseline: Claude Code 2.1.51 hook schema (session_id, cwd, transcript_path).

set -euo pipefail

INPUT=$(cat)

# Bash-only fallback logger for the pre-Python / no-Python branches (§20.2 C3).
# Never fails the hook: if even logging is impossible, we still exit 0.
_fallback_log() {
    local logdir="${HOME:-}/.aitools/logs"
    local logfile="$logdir/session-archive.log"
    local ts
    ts=$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo "unknown")
    # mkdir + append may fail if HOME unset / dir unwritable; that is acceptable
    # for a logging fallback -- the hook must not crash. Result is checked by the
    # || true and the surrounding exit 0.
    if mkdir -p "$logdir" 2>/dev/null; then
        printf '[%s] [session-archive] [%s] %s\n' "$ts" "${2:-warn}" "$1" \
            >> "$logfile" 2>/dev/null || true
    fi
}

# Resolve Python (existence check with explicit fallback -- error-handling rule 5).
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    _fallback_log "no Python on PATH; transcript not archived" "warn"
    exit 0
fi

# Resolve the helper (project root, then the canonical clone).
PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
HELPER=""
if [ -n "$PROJECT_ROOT" ] && [ -f "$PROJECT_ROOT/scripts/ait-harvest.py" ]; then
    HELPER="$PROJECT_ROOT/scripts/ait-harvest.py"
elif [ -f "$HOME/.claude/hooks/ait-harvest.py" ]; then
    HELPER="$HOME/.claude/hooks/ait-harvest.py"
elif [ -f "$HOME/repos/aitools/scripts/ait-harvest.py" ]; then
    HELPER="$HOME/repos/aitools/scripts/ait-harvest.py"
fi

if [ -z "$HELPER" ]; then
    _fallback_log "ait-harvest.py not found; transcript not archived" "warn"
    exit 0
fi

# Pass raw stdin; let stderr through (warnings visible). Never block.
if ! printf '%s' "$INPUT" | "$PYTHON" "$HELPER" archive; then
    _fallback_log "ait-harvest.py archive exited non-zero" "warn"
fi

exit 0
'@

$hook_catchup = @'
#!/usr/bin/env bash
# session-catchup.sh -- Claude Code SessionStart hook (thin shim)
# Recovers carry-forward that SessionEnd missed (abrupt exit / sleep / offline):
# archives orphaned CC transcripts globally and harvests orphaned scratch dirs.
# All logic, the single-flight lock, and logging live in ait-harvest.py
# (~/.aitools/logs/ait-harvest.log).
#
# Design (plan imperative-gliding-newell.md §4 + §16 + §20.1/§20.2):
#   - Standalone (no aitools-lib); bash-only on all platforms.
#   - Raw stdin -> python `catchup` (the helper reads session_id + cwd, and
#     skips its OWN session via the stdin session_id -- deterministic, never DB).
#   - Synchronous with a ~10s graceful deadline (in-Python; timeout(1) is not
#     portable). Single-flight: skips its sweep if another session holds the lock.
#   - Always exit 0; bash-fallback log on no-Python / no-helper / non-zero exit.

set -euo pipefail

INPUT=$(cat)

_fallback_log() {
    local logdir="${HOME:-}/.aitools/logs"
    local logfile="$logdir/session-catchup.log"
    local ts
    ts=$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo "unknown")
    if mkdir -p "$logdir" 2>/dev/null; then
        printf '[%s] [session-catchup] [%s] %s\n' "$ts" "${2:-warn}" "$1" \
            >> "$logfile" 2>/dev/null || true
    fi
}

PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    _fallback_log "no Python on PATH; catchup skipped" "warn"
    exit 0
fi

PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
HELPER=""
if [ -n "$PROJECT_ROOT" ] && [ -f "$PROJECT_ROOT/scripts/ait-harvest.py" ]; then
    HELPER="$PROJECT_ROOT/scripts/ait-harvest.py"
elif [ -f "$HOME/.claude/hooks/ait-harvest.py" ]; then
    HELPER="$HOME/.claude/hooks/ait-harvest.py"
elif [ -f "$HOME/repos/aitools/scripts/ait-harvest.py" ]; then
    HELPER="$HOME/repos/aitools/scripts/ait-harvest.py"
fi

if [ -z "$HELPER" ]; then
    _fallback_log "ait-harvest.py not found; catchup skipped" "warn"
    exit 0
fi

if ! printf '%s' "$INPUT" | "$PYTHON" "$HELPER" catchup --deadline 10; then
    _fallback_log "ait-harvest.py catchup exited non-zero" "warn"
fi

exit 0
'@

$hook_aitharvest = @'
#!/usr/bin/env python3
"""ait-harvest.py -- aitools session/scratch carry-forward harvester.

Purpose: One stdlib-only helper that owns every carry-forward source so the
SessionEnd hooks and a new SessionStart catch-up share a single, robust,
concurrency-safe implementation. Replaces the triplicated archive/harvest
logic in session-archive.sh / harvest-session.sh / `aitools sessions archive`.

Per-source functions (plan imperative-gliding-newell.md §4):
  - archive_claude_session: copy a CC transcript (and its subagents/*.jsonl)
    to the dotprofile under the flat naming sessions/<project>/<date>_<p8>.jsonl,
    then commit + push (deadline-guarded). Idempotent via dest-exists.
  - harvest_scratch: classify + route + manifest + prune a session's
    .scratch/session-<p10>/ dir (stdlib json; never deletes scratch dirs).
  - catchup: orchestrator -- archive orphaned transcripts globally, harvest
    orphaned scratch dirs in the current repo, push if ahead. Single-flight
    heartbeat lock; transcript-mtime liveness; skip own session via stdin sid.
  - archive_cursor_session: ROADMAP stub (issue #5).

Architecture (stdlib only): json, subprocess, pathlib, shutil, os, sys,
datetime, time, argparse, re, socket, logging.

Logging: ~/.aitools/logs/ait-harvest.log via RotatingFileHandler (5MB x 5),
format [<utc-Z>] [ait-harvest] [<level>] <msg>. Mirrors harness-db.py logging
but per reference/logging.md (unified location). Logging never crashes the tool.

Concurrency (plan §16 + §20.1):
  - Single-flight heartbeat lock at ~/.aitools/locks/harvest.lock via
    os.open(O_CREAT|O_EXCL) (atomic on POSIX and Windows; no flock/fcntl).
  - Holder refreshes the lock timestamp (heartbeat); a contender steals ONLY
    if the timestamp has not advanced past a threshold AND no .git/index.lock
    exists in the dotprofile. Never blocks -- skips its sweep when contended.
  - Release via try/finally + atexit.
  - Liveness PRIMARY guard = transcript mtime (>= ~30 min) + clean tail; the
    per-repo harness DB is at most a per-repo optimization, never the sole
    signal for the global sweep.
  - "Skip your own session" uses the session_id passed on stdin/argv,
    never a DB lookup.

Edge cases (plan §20.2):
  - Zero-byte/unparseable transcript -> skip + log.
  - Missing cwd in transcript -> fall back to sanitized projects-dir name.
  - Transient `claude update` session -> skip by positive signal.
  - AITOOLS_DEPLOY_IN_PROGRESS=1 -> catch-up skips its sweep.
  - dotprofile detached/mid-rebase/no-origin/no-upstream -> skip push, keep
    local commit, log specific reason (no silent exit 0).

Safe to re-run. Platform: macOS, Windows (Git Bash), Linux (Python 3.10+).
"""

from __future__ import annotations

import argparse
import atexit
import json
import logging
import logging.handlers
import os
import re
import shutil
import socket
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Optional

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

# Liveness: a transcript modified more recently than this is "possibly live".
# Conservative (plan §20.1: >= ~30 min, not 2 min) so a paused live session in
# another repo is never archived mid-flight.
LIVE_MTIME_SECONDS = 30 * 60  # 30 minutes

# A transcript with fewer than this many records is treated as a transient
# `claude update` session (positive signal, plan §20.2 M2).
TRANSIENT_MIN_RECORDS = 3

# Lock heartbeat: holder refreshes the lockfile timestamp this often; a
# contender steals only if the timestamp is older than the steal threshold.
LOCK_HEARTBEAT_SECONDS = 15
LOCK_STALE_SECONDS = 90  # plan §20.1: SessionEnd git is not deadline-bounded

# Archive filename prefix length. Matches existing archives + `aitools sessions
# archive` (session-archive.sh:90). NOTE: scratch dir lookup uses 10 chars to
# match scratch-init.sh -- see SCRATCH_PREFIX_LEN.
ARCHIVE_PREFIX_LEN = 8

# Scratch dir prefix length. Must match scratch-init.sh (cut -c1-10) and
# harness-db.py session_prefix() -- the dir on disk is session-<10char>.
SCRATCH_PREFIX_LEN = 10

LOG_MAX_BYTES = 5 * 1024 * 1024  # 5 MB (reference/logging.md)
LOG_BACKUP_COUNT = 5


# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

_LOGGER: Optional[logging.Logger] = None


def _log_dir() -> Path:
    """Unified aitools log directory (reference/logging.md)."""
    return Path.home() / ".aitools" / "logs"


def _get_logger() -> logging.Logger:
    """Lazily build the module logger. Never raises -- logging must not crash
    the tool (reference/logging.md decision 5)."""
    global _LOGGER
    if _LOGGER is not None:
        return _LOGGER

    logger = logging.getLogger("ait-harvest")
    logger.setLevel(logging.DEBUG)
    logger.propagate = False

    try:
        log_dir = _log_dir()
        log_dir.mkdir(parents=True, exist_ok=True)
        handler: logging.Handler = logging.handlers.RotatingFileHandler(
            log_dir / "ait-harvest.log",
            maxBytes=LOG_MAX_BYTES,
            backupCount=LOG_BACKUP_COUNT,
            encoding="utf-8",
        )
    except OSError:
        # $HOME unset, dir unwritable, etc. Fall back to a null handler so the
        # tool keeps running (the shim logs the no-log condition from bash).
        handler = logging.NullHandler()

    # Custom format: [<utc-Z>] [ait-harvest] [<level>] <msg>
    class _UtcFormatter(logging.Formatter):
        _LEVELMAP = {
            "DEBUG": "detail",
            "INFO": "info",
            "WARNING": "warn",
            "ERROR": "error",
            "CRITICAL": "error",
        }

        def format(self, record: logging.LogRecord) -> str:
            ts = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            level = self._LEVELMAP.get(record.levelname, record.levelname.lower())
            return f"[{ts}] [ait-harvest] [{level}] {record.getMessage()}"

    handler.setFormatter(_UtcFormatter())
    logger.addHandler(handler)
    _LOGGER = logger
    return logger


def log_info(msg: str) -> None:
    _get_logger().info(msg)


def log_ok(msg: str) -> None:
    # No dedicated OK level in stdlib logging; map to info with an 'ok:' marker
    # so deploy.log readers can still grep. Kept distinct from plain info.
    _get_logger().info(f"ok: {msg}")


def log_warn(msg: str) -> None:
    _get_logger().warning(msg)


def log_error(msg: str) -> None:
    _get_logger().error(msg)


def log_detail(msg: str) -> None:
    _get_logger().debug(msg)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def utcnow() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def today_utc() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")


def sanitize_project(name: str) -> str:
    """Lowercase + replace non [a-z0-9-] with '-' (matches the bash hooks)."""
    return re.sub(r"[^a-z0-9-]", "-", name.lower())


def read_config_user_repo() -> Optional[Path]:
    """Read userRepoPath (the dotprofile) from ~/.aitools/config.json.

    Returns the path if it exists on disk, else None (logged)."""
    config_file = Path.home() / ".aitools" / "config.json"
    if not config_file.exists():
        log_detail("skipped: aitools config.json not found")
        return None
    try:
        data = json.loads(config_file.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as e:
        log_warn(f"could not read config.json: {e}")
        return None
    raw = data.get("userRepoPath")
    if not raw:
        log_detail("skipped: userRepoPath not set in config.json")
        return None
    repo = Path(raw).expanduser()
    if not repo.is_dir():
        log_detail(f"skipped: userRepoPath does not exist: {repo}")
        return None
    return repo


def git_root(cwd: Path) -> Optional[Path]:
    """Return the git toplevel for cwd, or None. Never raises."""
    try:
        out = subprocess.run(
            ["git", "-C", str(cwd), "rev-parse", "--show-toplevel"],
            capture_output=True, text=True, timeout=10,
        )
    except (OSError, subprocess.SubprocessError) as e:
        log_detail(f"git rev-parse failed for {cwd}: {e}")
        return None
    if out.returncode != 0:
        return None
    top = out.stdout.strip()
    return Path(top) if top else None


def first_record_cwd_and_count(transcript: Path) -> tuple[Optional[str], int]:
    """Return (cwd-from-first-record-with-cwd, total-record-count).

    cwd is None if no record carries a cwd field. Count is the number of
    JSON-parseable lines (used for the transient-session signal). Never raises;
    returns (None, 0) on read errors (caller treats as empty/unreadable)."""
    cwd: Optional[str] = None
    count = 0
    try:
        with open(transcript, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                except json.JSONDecodeError:
                    continue
                count += 1
                if cwd is None and isinstance(rec, dict) and rec.get("cwd"):
                    cwd = str(rec["cwd"])
    except OSError as e:
        log_detail(f"could not read transcript {transcript.name}: {e}")
        return None, 0
    return cwd, count


def derive_project(transcript: Path, cwd: Optional[str]) -> str:
    """Derive the archive project name (plan §4 + §20.2 M1 fallbacks).

    1. cwd present -> git root basename, else sanitized cwd basename.
    2. cwd missing/repo-gone -> sanitized projects-dir name (old behavior)."""
    if cwd:
        cwd_path = Path(cwd)
        root = git_root(cwd_path) if cwd_path.is_dir() else None
        if root is not None:
            return root.name
        # cwd recorded but repo gone/renamed -> still archive under cwd basename.
        return sanitize_project(cwd_path.name)
    # No cwd in the transcript: fall back to the sanitized projects-dir name.
    log_detail(f"cwd-derive failed for {transcript.name}, using dir name")
    return sanitize_project(transcript.parent.name)


def transcript_date(transcript: Path) -> str:
    """Date for the archive filename: file mtime (UTC), fallback today.

    The bash hook uses birth time where available; mtime is portable and
    close enough, and this matches `aitools sessions archive` on non-macOS."""
    try:
        mtime = transcript.stat().st_mtime
        return datetime.fromtimestamp(mtime, tz=timezone.utc).strftime("%Y-%m-%d")
    except OSError:
        return today_utc()


# ---------------------------------------------------------------------------
# Single-flight heartbeat lock (plan §16 + §20.1)
# ---------------------------------------------------------------------------

class HarvestLock:
    """Atomic single-flight lock with heartbeat + steal-on-stale.

    Acquire returns True if the lock is held by this process, False if a live
    holder exists (caller must SKIP its sweep -- never block, plan §20.1 C2).
    The holder must periodically call heartbeat(). Release is idempotent and
    registered with atexit + used in try/finally by callers (plan §20.1 m2)."""

    def __init__(self, dotprofile: Optional[Path]) -> None:
        self.path = Path.home() / ".aitools" / "locks" / "harvest.lock"
        self.dotprofile = dotprofile
        self.held = False
        self._fd: Optional[int] = None

    def _write_payload(self, fd: int) -> None:
        payload = json.dumps({
            "pid": os.getpid(),
            "host": socket.gethostname(),
            "start": utcnow(),
            "heartbeat": time.time(),
        })
        os.lseek(fd, 0, os.SEEK_SET)
        os.ftruncate(fd, 0)
        os.write(fd, payload.encode("utf-8"))
        os.fsync(fd)

    def _read_heartbeat(self) -> Optional[float]:
        try:
            data = json.loads(self.path.read_text(encoding="utf-8"))
            hb = data.get("heartbeat")
            return float(hb) if hb is not None else None
        except (OSError, json.JSONDecodeError, TypeError, ValueError):
            return None

    def _dotprofile_index_locked(self) -> bool:
        """True if the dotprofile has a live .git/index.lock (plan §20.1 C1).
        Conservative: if we cannot tell, return True (do not steal)."""
        if self.dotprofile is None:
            return False
        try:
            return (self.dotprofile / ".git" / "index.lock").exists()
        except OSError:
            return True

    def acquire(self) -> bool:
        # m1: ensure the lock directory exists first; failure -> cannot lock,
        # caller skips (do not crash).
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            log_warn(f"cannot create lock dir, skipping sweep: {e}")
            return False

        try:
            self._fd = os.open(
                str(self.path), os.O_CREAT | os.O_EXCL | os.O_RDWR
            )
            self._write_payload(self._fd)
            self.held = True
            atexit.register(self.release)
            log_detail("lock acquired")
            return True
        except FileExistsError:
            pass
        except OSError as e:
            log_warn(f"lock open failed, skipping sweep: {e}")
            return False

        # Lock exists. Steal ONLY if heartbeat is stale AND dotprofile has no
        # live index.lock (plan §20.1 C1). Never block.
        hb = self._read_heartbeat()
        if hb is None:
            # Unreadable/corrupt lock: treat as stale only if the file itself
            # is older than the stale threshold (mtime), to avoid racing a
            # holder mid-write.
            try:
                age = time.time() - self.path.stat().st_mtime
            except OSError:
                age = 0.0
            stale = age > LOCK_STALE_SECONDS
        else:
            stale = (time.time() - hb) > LOCK_STALE_SECONDS

        if not stale:
            log_detail("lock held by live process, skipping sweep")
            return False
        if self._dotprofile_index_locked():
            log_detail("lock stale but dotprofile index.lock present, skipping")
            return False

        # Steal: remove the orphaned lock and re-acquire. Document the degraded
        # window (a crashed holder leaves a <= LOCK_STALE_SECONDS gap).
        log_warn(f"stealing stale lock (heartbeat > {LOCK_STALE_SECONDS}s)")
        try:
            os.remove(str(self.path))
        except OSError as e:
            log_warn(f"could not remove stale lock, skipping: {e}")
            return False
        try:
            self._fd = os.open(
                str(self.path), os.O_CREAT | os.O_EXCL | os.O_RDWR
            )
            self._write_payload(self._fd)
            self.held = True
            atexit.register(self.release)
            log_detail("lock acquired after steal")
            return True
        except OSError as e:
            # Another contender won the race -- skip.
            log_detail(f"lost steal race, skipping: {e}")
            return False

    def heartbeat(self) -> None:
        if self.held and self._fd is not None:
            try:
                self._write_payload(self._fd)
            except OSError as e:
                log_detail(f"heartbeat write failed: {e}")

    def release(self) -> None:
        if not self.held:
            return
        self.held = False
        if self._fd is not None:
            try:
                os.close(self._fd)
            except OSError:
                pass
            self._fd = None
        try:
            os.remove(str(self.path))
            log_detail("lock released")
        except OSError:
            pass


# ---------------------------------------------------------------------------
# Git operations (deadline-guarded, dotprofile-state aware)
# ---------------------------------------------------------------------------

def _git(repo: Path, args: list[str], remaining: float) -> tuple[int, str, str]:
    """Run a git command with a timeout derived from the deadline budget.
    Returns (returncode, stdout, stderr). returncode 124 == timed out / error."""
    timeout = max(1.0, remaining)
    try:
        out = subprocess.run(
            ["git", "-C", str(repo), *args],
            capture_output=True, text=True, timeout=timeout,
        )
        return out.returncode, out.stdout.strip(), out.stderr.strip()
    except subprocess.TimeoutExpired:
        log_warn(f"git {args[0]} timed out after {timeout:.0f}s")
        return 124, "", "timeout"
    except (OSError, subprocess.SubprocessError) as e:
        log_warn(f"git {args[0]} failed: {e}")
        return 124, "", str(e)


def dotprofile_push_blocked_reason(repo: Path, remaining: float) -> Optional[str]:
    """Return a reason string if the dotprofile is NOT in a clean state to push,
    else None (plan §20.2 M6). Checks: mid-rebase/merge, no origin, no upstream,
    detached HEAD."""
    git_dir = repo / ".git"
    try:
        if (git_dir / "MERGE_HEAD").exists():
            return "merge in progress"
        for rebase in ("rebase-merge", "rebase-apply"):
            if (git_dir / rebase).exists():
                return "rebase in progress"
    except OSError:
        return "cannot inspect .git state"

    rc, _, _ = _git(repo, ["remote", "get-url", "origin"], remaining)
    if rc != 0:
        return "no origin remote"

    rc, out, _ = _git(
        repo, ["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"],
        remaining,
    )
    if rc != 0 or not out:
        return "no upstream for current branch"

    rc, head, _ = _git(repo, ["symbolic-ref", "-q", "HEAD"], remaining)
    if rc != 0 or not head:
        return "detached HEAD"

    return None


def commit_and_push(
    repo: Path, rel_path: str, commit_msg: str, deadline: float,
) -> None:
    """Stage one file, commit, and push if the dotprofile is clean. Best-effort:
    every failure path logs a specific reason; the local commit is preserved on
    push failure (plan §20.2 M6 / pass 4 -- no silent exit)."""
    def remaining() -> float:
        return deadline - time.monotonic()

    if remaining() <= 0:
        log_warn(f"deadline exceeded before git add ({rel_path})")
        return

    rc, _, err = _git(repo, ["add", rel_path], remaining())
    if rc != 0:
        log_warn(f"git add failed for {rel_path}: {err}")
        return

    rc, _, err = _git(repo, ["commit", "-m", commit_msg], remaining())
    if rc != 0:
        # Nothing to commit is benign (already staged/committed by a peer).
        log_detail(f"git commit produced no commit ({rel_path}): {err}")
        return
    log_ok(f"committed {rel_path}")

    reason = dotprofile_push_blocked_reason(repo, remaining())
    if reason is not None:
        log_warn(f"push skipped, commit kept: {reason}")
        return

    # Pull --rebase handles the cross-machine race; the lock handles same-machine.
    rc, _, err = _git(repo, ["pull", "--rebase"], remaining())
    if rc != 0:
        log_warn(f"git pull --rebase failed, push skipped, commit kept: {err}")
        return

    rc, _, err = _git(repo, ["push"], remaining())
    if rc != 0:
        log_warn(f"git push failed (offline or remote ahead), commit kept: {err}")
        return
    log_ok(f"pushed {rel_path}")


def dotprofile_is_ahead(repo: Path, remaining: float) -> bool:
    """True if the local branch has commits not on its upstream."""
    rc, out, _ = _git(
        repo, ["rev-list", "--count", "@{u}..HEAD"], remaining
    )
    if rc != 0:
        return False
    try:
        return int(out) > 0
    except ValueError:
        return False


# ---------------------------------------------------------------------------
# archive_claude_session
# ---------------------------------------------------------------------------

def archive_claude_session(
    transcript: Path,
    cwd: Optional[str],
    session_id: Optional[str],
    *,
    user_repo: Optional[Path] = None,
    deadline: Optional[float] = None,
    do_git: bool = True,
) -> bool:
    """Archive one CC transcript (+ subagents) to the dotprofile.

    Returns True if a new file was written, False if skipped (already archived,
    empty, no config, etc. -- each logged at detail). Idempotent."""
    if user_repo is None:
        user_repo = read_config_user_repo()
        if user_repo is None:
            return False

    if not transcript.exists():
        log_detail(f"skipped: transcript missing {transcript}")
        return False

    # Zero-byte / unreadable guard (plan §20.2 M1).
    try:
        if transcript.stat().st_size == 0:
            log_detail(f"skipped: empty (zero-byte) transcript {transcript.name}")
            return False
    except OSError as e:
        log_detail(f"skipped: cannot stat {transcript.name}: {e}")
        return False

    if cwd is None:
        cwd, _ = first_record_cwd_and_count(transcript)

    project = derive_project(transcript, cwd)
    full_id = transcript.stem  # filename without .jsonl == session id
    prefix = full_id[:ARCHIVE_PREFIX_LEN]
    date = transcript_date(transcript)

    dest_dir = user_repo / "sessions" / project
    dest_file = dest_dir / f"{date}_{prefix}.jsonl"

    if dest_file.exists():
        log_detail(f"skipped: already archived {project}/{date}_{prefix}.jsonl")
        return False

    try:
        dest_dir.mkdir(parents=True, exist_ok=True)
        shutil.copy2(str(transcript), str(dest_file))
    except OSError as e:
        log_error(f"failed to copy transcript {transcript.name}: {e}")
        return False
    log_ok(f"archived {project}/{date}_{prefix}.jsonl")

    rel_paths = [f"sessions/{project}/{date}_{prefix}.jsonl"]

    # --- Subagent transcripts (plan §3/§4: never archived before) ---
    # Located at <transcript-dir>/<session-id>/subagents/*.jsonl OR
    # <transcript-dir>/subagents/*.jsonl depending on CC version. Copy as flat
    # siblings: <date>_<p8>_subagent-<n>.jsonl (NOT a directory).
    subagent_dirs = [
        transcript.parent / full_id / "subagents",
        transcript.parent / "subagents",
    ]
    n = 0
    for sad in subagent_dirs:
        if not sad.is_dir():
            continue
        try:
            sub_files = sorted(sad.glob("*.jsonl"))
        except OSError:
            sub_files = []
        for sub in sub_files:
            n += 1
            sub_dest = dest_dir / f"{date}_{prefix}_subagent-{n}.jsonl"
            if sub_dest.exists():
                continue
            try:
                shutil.copy2(str(sub), str(sub_dest))
                rel_paths.append(
                    f"sessions/{project}/{date}_{prefix}_subagent-{n}.jsonl"
                )
                log_ok(f"archived subagent {sub_dest.name}")
            except OSError as e:
                log_warn(f"failed to copy subagent {sub.name}: {e}")

    # --- Commit + push (deadline-guarded) ---
    if do_git:
        if deadline is None:
            deadline = time.monotonic() + 10.0
        commit_msg = f"Archive session {date}_{prefix} ({project})"
        # Stage all archived files (transcript + subagents) in one commit.
        for rp in rel_paths:
            rc, _, err = _git(user_repo, ["add", rp], deadline - time.monotonic())
            if rc != 0:
                log_warn(f"git add failed for {rp}: {err}")
        # Single commit + push via the shared path (re-stages safely).
        commit_and_push(user_repo, rel_paths[0], commit_msg, deadline)

    return True


# ---------------------------------------------------------------------------
# harvest_scratch (ports harvest-session.sh, stdlib json, no node)
# ---------------------------------------------------------------------------

CODE_EXTS = {".py", ".sh", ".ps1", ".js", ".ts", ".go", ".rs", ".pl"}
ARTIFACT_EXTS = {".yaml", ".yml", ".toml", ".csv", ".sql", ".html", ".txt"}
LANG_MAP = {
    "py": "python", "sh": "bash", "ps1": "powershell", "js": "javascript",
    "ts": "typescript", "go": "go", "rs": "rust", "pl": "perl", "md": "markdown",
}


def _is_ephemeral(filename: str) -> bool:
    """Classification mirroring harvest-session.sh (extension + name)."""
    lower = filename.lower()
    if lower.startswith("commit-msg") or lower.endswith((".log", ".tmp")):
        return True
    ext = "." + filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    if ext in CODE_EXTS:
        return False
    if ext == ".json":
        if (lower.startswith("package-lock") or lower.startswith("node_modules")
                or lower.endswith(".config.json") or lower.startswith("tsconfig")):
            return True
        return False
    if ext == ".md":
        if "log" in lower or "output" in lower or "dump" in lower:
            return True
        return False
    if ext in ARTIFACT_EXTS:
        return False
    # Unknown extension: harvest with warning rather than silently delete.
    return False


def _atomic_write_json(path: Path, data: dict[str, Any]) -> None:
    """Write JSON atomically via temp file + os.replace (plan §16)."""
    tmp = path.with_name(path.name + f".tmp.{os.getpid()}")
    tmp.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
    os.replace(str(tmp), str(path))


def _load_manifest(path: Path) -> dict[str, Any]:
    if path.exists():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                data.setdefault("meta", {"schemaVersion": "1.0", "lastAudit": None})
                data.setdefault("artifacts", {})
                return data
        except (OSError, json.JSONDecodeError) as e:
            log_warn(f"manifest unreadable, starting fresh: {e}")
    return {"meta": {"schemaVersion": "1.0", "lastAudit": None}, "artifacts": {}}


def harvest_scratch(
    cwd: str,
    session_id: Optional[str],
    *,
    project_root: Optional[Path] = None,
) -> int:
    """Classify + route + manifest a session's scratch dir. Returns the number
    of artifacts harvested. Never deletes scratch dirs (30-file-loss guard).
    Leaves DB session-end marking to harness-db-sessionend.sh."""
    if project_root is None:
        root = git_root(Path(cwd)) if cwd and Path(cwd).is_dir() else None
        project_root = root if root is not None else Path(cwd)

    scratch_dir = project_root / ".scratch"
    prefix = session_id[:SCRATCH_PREFIX_LEN] if session_id else ""

    session_dir: Optional[Path] = None
    if prefix and (scratch_dir / f"session-{prefix}").is_dir():
        session_dir = scratch_dir / f"session-{prefix}"
    else:
        current = scratch_dir / ".current-session"
        if current.exists():
            try:
                p = current.read_text(encoding="utf-8").strip()
                if p and Path(p).is_dir():
                    session_dir = Path(p)
            except OSError:
                pass

    if session_dir is None or not session_dir.is_dir():
        log_detail(f"skipped harvest: no session dir for {prefix or '(none)'}")
        return 0

    harvesting_dir = project_root / "harvesting"
    handoffs_dir = project_root / ".aitools" / "channel" / "handoffs"
    manifest_path = harvesting_dir / "harvest-manifest.json"
    today = today_utc()
    harvested = 0
    deleted = 0

    try:
        files = sorted(p for p in session_dir.iterdir() if p.is_file())
    except OSError as e:
        log_warn(f"cannot list session dir {session_dir}: {e}")
        return 0

    manifest: Optional[dict[str, Any]] = None

    for f in files:
        filename = f.name
        if _is_ephemeral(filename):
            deleted += 1
            continue

        # Handoff routing.
        if filename.startswith("handoff"):
            try:
                handoffs_dir.mkdir(parents=True, exist_ok=True)
                dest = handoffs_dir / f"{today}_session-{prefix}_{filename}"
                shutil.copy2(str(f), str(dest))
                harvested += 1
                log_ok(f"routed handoff {dest.name}")
            except OSError as e:
                log_warn(f"handoff copy failed for {filename}: {e}")
            continue

        # Harvest to harvesting/.
        try:
            harvesting_dir.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            log_warn(f"cannot create harvesting dir: {e}")
            continue

        session_tag = f"session-{prefix}_" if prefix else ""
        dest_name = f"{today}_{session_tag}{filename}"
        dest_path = harvesting_dir / dest_name
        if dest_path.exists():
            counter = 1
            while (harvesting_dir / f"{today}_{counter}_{session_tag}{filename}").exists():
                counter += 1
            dest_name = f"{today}_{counter}_{session_tag}{filename}"
            dest_path = harvesting_dir / dest_name

        try:
            shutil.copy2(str(f), str(dest_path))
        except OSError as e:
            log_warn(f"harvest copy failed for {filename}: {e}")
            continue

        if manifest is None:
            manifest = _load_manifest(manifest_path)
        ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
        project_name = project_root.name
        session_ref = f"{project_name}/{today}_{prefix}" if cwd else ""
        # pruneAfter = today + 30 days.
        prune_after = datetime.now(timezone.utc).timestamp() + 30 * 86400
        prune_date = datetime.fromtimestamp(
            prune_after, tz=timezone.utc).strftime("%Y-%m-%d")
        manifest["artifacts"][dest_name] = {
            "harvested": today,
            "session": session_ref,
            "description": "Auto-harvested from session scratch",
            "type": "code",
            "language": LANG_MAP.get(ext),
            "status": "harvested",
            "promotedTo": None,
            "pruneAfter": prune_date,
        }
        harvested += 1
        log_ok(f"harvested {dest_name}")

    if manifest is not None:
        try:
            _atomic_write_json(manifest_path, manifest)
        except OSError as e:
            log_warn(f"manifest write failed: {e}")

    # Clear the legacy session pointer (leave the session dir intact).
    try:
        (scratch_dir / ".current-session").unlink()
    except OSError:
        pass

    # Audit/prune the manifest (mark pruned, never unlink -- 30-file-loss guard).
    _audit_manifest(manifest_path, harvesting_dir, project_root)

    if harvested or deleted:
        log_info(
            f"harvest {prefix or 'unknown'}: {harvested} harvested, "
            f"{deleted} ephemeral skipped"
        )
    return harvested


def _audit_manifest(
    manifest_path: Path, harvesting_dir: Path, project_root: Path,
) -> None:
    """Prune stale artifacts: mark 'pruned' (never delete the file) when past
    pruneAfter with zero git refs, else promote to 'candidate'."""
    if not manifest_path.exists():
        return
    manifest = _load_manifest(manifest_path)
    today = datetime.now(timezone.utc).date()
    changed = False
    for name, entry in manifest.get("artifacts", {}).items():
        status = entry.get("status")
        if status in ("promoted", "pruned"):
            continue
        prune_after = entry.get("pruneAfter")
        if not prune_after:
            continue
        try:
            prune_date = datetime.strptime(prune_after, "%Y-%m-%d").date()
        except (ValueError, TypeError):
            continue
        if today <= prune_date:
            continue
        # Past prune date: check git refs.
        refs = 0
        try:
            out = subprocess.run(
                ["git", "-C", str(project_root), "log", "--all", "--oneline",
                 "--", str(harvesting_dir / name)],
                capture_output=True, text=True, timeout=5,
            )
            if out.returncode == 0:
                refs = len([ln for ln in out.stdout.splitlines() if ln.strip()])
        except (OSError, subprocess.SubprocessError):
            refs = 0
        if refs == 0:
            entry["status"] = "pruned"  # marked, NOT deleted
        else:
            entry["status"] = "candidate"
        changed = True
    if changed:
        manifest.setdefault("meta", {})["lastAudit"] = today_utc()
        try:
            _atomic_write_json(manifest_path, manifest)
        except OSError as e:
            log_warn(f"manifest audit write failed: {e}")


# ---------------------------------------------------------------------------
# catchup (orchestrator)
# ---------------------------------------------------------------------------

def _is_transient_session(transcript: Path) -> bool:
    """Positive signal for a transient `claude update` session (plan §20.2 M2):
    a transcript with very few records."""
    _, count = first_record_cwd_and_count(transcript)
    return 0 < count < TRANSIENT_MIN_RECORDS


def catchup(
    cwd: str,
    session_id: Optional[str],
    deadline_seconds: float = 10.0,
) -> int:
    """Recover what SessionEnd missed: archive orphaned CC transcripts globally,
    harvest the current repo's orphaned scratch dirs, push if ahead. Single-
    flight; skips its sweep if contended or during an aitools deploy."""
    # Skip during an in-flight aitools deploy (plan §20.2 M2).
    if os.environ.get("AITOOLS_DEPLOY_IN_PROGRESS"):
        log_detail("skipped catchup: AITOOLS_DEPLOY_IN_PROGRESS set")
        return 0

    user_repo = read_config_user_repo()
    lock = HarvestLock(user_repo)
    if not lock.acquire():
        # Contended -- the holder covers the global orphan set. Skip, stay fast.
        return 0

    recovered = 0
    deadline = time.monotonic() + deadline_seconds
    try:
        recovered += _catchup_archive(user_repo, session_id, deadline, lock)
        lock.heartbeat()
        # Harvest orphaned scratch dirs in the current repo.
        recovered += _catchup_harvest(cwd, session_id)
        lock.heartbeat()
        # Push if the dotprofile is ahead (e.g. a prior commit never pushed).
        if user_repo is not None:
            remaining = deadline - time.monotonic()
            if remaining > 0 and dotprofile_is_ahead(user_repo, remaining):
                reason = dotprofile_push_blocked_reason(user_repo, remaining)
                if reason is None:
                    rc, _, err = _git(
                        user_repo, ["push"], deadline - time.monotonic())
                    if rc == 0:
                        log_ok("pushed dotprofile (was ahead)")
                    else:
                        log_warn(f"dotprofile push failed, commit kept: {err}")
                else:
                    log_warn(f"dotprofile ahead but push skipped: {reason}")
    finally:
        lock.release()

    if recovered:
        log_info(f"catchup recovered {recovered} item(s)")
    return recovered


def _catchup_archive(
    user_repo: Optional[Path],
    session_id: Optional[str],
    deadline: float,
    lock: HarvestLock,
) -> int:
    """Scan ~/.claude/projects/*/*.jsonl; archive any orphaned, non-live,
    non-transient transcript that has no dotprofile dest yet."""
    if user_repo is None:
        return 0
    projects = Path.home() / ".claude" / "projects"
    if not projects.is_dir():
        return 0

    recovered = 0
    now = time.time()
    try:
        transcripts = sorted(projects.glob("*/*.jsonl"))
    except OSError as e:
        log_warn(f"cannot scan projects dir: {e}")
        return 0

    for t in transcripts:
        if deadline - time.monotonic() <= 0:
            log_warn("catchup archive: deadline reached, stopping sweep")
            break
        lock.heartbeat()

        full_id = t.stem
        # Skip our own session via stdin/argv sid (deterministic, plan §20.1).
        if session_id and full_id.startswith(session_id[:max(8, len(session_id))]):
            continue
        if session_id and full_id == session_id:
            continue

        # Liveness PRIMARY guard: mtime >= LIVE_MTIME_SECONDS (plan §20.1).
        try:
            mtime = t.stat().st_mtime
            size = t.stat().st_size
        except OSError:
            continue
        if size == 0:
            log_detail(f"skipped: empty transcript {t.name}")
            continue
        if (now - mtime) < LIVE_MTIME_SECONDS:
            log_detail(f"skipped: possibly-live transcript {t.name} (recent mtime)")
            continue

        # Transient `claude update` session (positive signal).
        if _is_transient_session(t):
            log_detail(f"skipped: transient/update session {t.name}")
            continue

        if archive_claude_session(
            t, None, None, user_repo=user_repo, deadline=deadline, do_git=True
        ):
            recovered += 1

    return recovered


def _catchup_harvest(cwd: str, session_id: Optional[str]) -> int:
    """Harvest orphaned .scratch/session-* dirs in the current repo whose
    SessionEnd never ran. Skips the current session's own dir."""
    root = git_root(Path(cwd)) if cwd and Path(cwd).is_dir() else None
    project_root = root if root is not None else Path(cwd) if cwd else None
    if project_root is None or not project_root.is_dir():
        return 0
    scratch_dir = project_root / ".scratch"
    if not scratch_dir.is_dir():
        return 0

    own_prefix = session_id[:SCRATCH_PREFIX_LEN] if session_id else None
    recovered = 0
    try:
        session_dirs = [
            p for p in scratch_dir.iterdir()
            if p.is_dir() and p.name.startswith("session-")
        ]
    except OSError:
        return 0

    for sd in session_dirs:
        dir_prefix = sd.name[len("session-"):]
        if own_prefix and dir_prefix == own_prefix:
            continue  # never harvest our own live session
        recovered += harvest_scratch(
            str(project_root), dir_prefix, project_root=project_root
        )
    return recovered


# ---------------------------------------------------------------------------
# archive_cursor_session (ROADMAP stub -- issue #5)
# ---------------------------------------------------------------------------

def archive_cursor_session(*_args: Any, **_kwargs: Any) -> int:
    """ROADMAP stub: Cursor CLI sessions live in ~/.cursor/chats/*/store.db
    (SQLite with live WAL). Safe archiving requires a sqlite3 .backup / WAL
    checkpoint plus a workspace-hash -> project mapping. Deferred to issue #5."""
    log_detail("archive_cursor_session is a stub (issue #5); no-op")
    return 0


# ---------------------------------------------------------------------------
# stdin / argv parsing
# ---------------------------------------------------------------------------

def _read_stdin_json() -> dict[str, Any]:
    """Read a CC hook JSON payload from stdin if present. Returns {} on any
    error (the shim passes raw stdin; argv flags can override)."""
    if sys.stdin is None or sys.stdin.isatty():
        return {}
    try:
        raw = sys.stdin.read()
    except (OSError, ValueError):
        return {}
    if not raw.strip():
        return {}
    try:
        data = json.loads(raw)
        return data if isinstance(data, dict) else {}
    except json.JSONDecodeError:
        log_detail("stdin was not valid JSON; ignoring")
        return {}


# ---------------------------------------------------------------------------
# Subcommands
# ---------------------------------------------------------------------------

def cmd_archive(args: argparse.Namespace) -> int:
    payload = _read_stdin_json()
    session_id = args.session or payload.get("session_id")
    cwd = args.cwd or payload.get("cwd")
    transcript_path = args.transcript or payload.get("transcript_path")
    if not transcript_path:
        log_detail("archive: no transcript_path on stdin/argv; nothing to do")
        return 0
    transcript = Path(transcript_path)
    archive_claude_session(transcript, cwd, session_id)
    return 0


def cmd_harvest(args: argparse.Namespace) -> int:
    payload = _read_stdin_json()
    session_id = args.session or payload.get("session_id")
    cwd = args.cwd or payload.get("cwd") or os.getcwd()
    harvest_scratch(cwd, session_id)
    return 0


def cmd_catchup(args: argparse.Namespace) -> int:
    payload = _read_stdin_json()
    session_id = args.session or payload.get("session_id")
    cwd = args.cwd or payload.get("cwd") or os.getcwd()
    catchup(cwd, session_id, deadline_seconds=args.deadline)
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="ait-harvest.py",
        description="aitools session/scratch carry-forward harvester",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    p_archive = sub.add_parser("archive", help="archive a CC transcript")
    p_archive.add_argument("--session", help="session id (else from stdin)")
    p_archive.add_argument("--cwd", help="working dir (else from stdin/transcript)")
    p_archive.add_argument("--transcript", help="transcript path (else from stdin)")
    p_archive.set_defaults(func=cmd_archive)

    p_harvest = sub.add_parser("harvest", help="harvest a session's scratch dir")
    p_harvest.add_argument("--session", help="session id (else from stdin)")
    p_harvest.add_argument("--cwd", help="working dir (else from stdin/cwd)")
    p_harvest.set_defaults(func=cmd_harvest)

    p_catchup = sub.add_parser("catchup", help="recover what SessionEnd missed")
    p_catchup.add_argument("--session", help="current session id (else from stdin)")
    p_catchup.add_argument("--cwd", help="current working dir (else from stdin/cwd)")
    p_catchup.add_argument(
        "--deadline", type=float, default=10.0,
        help="graceful deadline in seconds (default 10)",
    )
    p_catchup.set_defaults(func=cmd_catchup)

    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    try:
        return args.func(args)
    except Exception as e:  # noqa: BLE001 -- top-level guard, must log then exit 0
        # The hook must never break Claude Code: log and exit 0.
        log_error(f"unhandled error in {args.command}: {e}")
        return 0


if __name__ == "__main__":
    sys.exit(main())
'@

$hook_guard = @'
#!/usr/bin/env bash
# standing-order-guard.sh — Claude Code PreToolUse hook
# Purpose: Enforce standing orders by inspecting Bash tool calls before
#   execution. Catches USO violations that would otherwise trigger
#   permission prompts or bypass dedicated tools.
# Scope: USO enforcement only (dedicated tools, scratch files, simple
#   bash commands). NOT agentic standards, NOT script-standards compliance.
# Audience: Claude Code PreToolUse hook system — fires on every Bash call.
#
# Enforces:
#   USO: Dedicated tools for file ops (Read/Edit/Write/Grep/Glob, not Bash)
#   USO: Scratch files for complex scripting (no long inline commands)
#   USO: Simple Bash commands only (no &&, ||, ;, $(...), backticks, globs in rm)
#
# Hook contract:
#   - Receives JSON on stdin (tool_name, tool_input.command, etc.)
#   - Exit 0 = allow
#   - Exit 2 = block (stderr becomes Claude's feedback)
#   - Must never crash or hang (would break Claude Code)
#
# Rollout mode (per-check):
#   MODE_AND="enforce"       — && : zero false positives confirmed, blocking
#   MODE_SUBSHELL="enforce"  — $(): zero false positives confirmed, blocking
#   MODE_SCRATCH="enforce"   — scratch files: zero false positives confirmed, blocking
#   MODE_OR="enforce"        — || : zero false positives, promoted 2026-03-24
#   MODE_SEMICOLON="enforce" — ;  : pwsh/perl exemptions in place, promoted 2026-03-24
#   MODE_BACKTICK="enforce"  — backticks: zero false positives, promoted 2026-03-24
#   See .claude/rules/hook-rollout.md for the observe-then-enforce practice.
#
# Design decisions:
#   - Pure-bash JSON parsing (jq not guaranteed in hook environment)
#   - Conservative matching: only flag clear violations, allow ambiguous cases
#   - Helpful feedback: tell Claude which tool to use instead
#   - Pipeline exemption: cat/head/tail in pipelines (cmd | ...) are allowed
#     because the Read tool cannot pipe output into other commands
#
# KPI definitions (emit to log, future: structured JSONL):
#   - guardFireCount: total hook invocations per session
#   - guardBlockCount: violations blocked (exit 2) per session
#   - guardObserveCount: violations observed but allowed per session
#   - falsePositiveRate: user-reported false positives / total blocks

set -euo pipefail

# --- Mode and logging ---
MODE_AND="enforce"       # &&  — zero false positives confirmed; blocking
MODE_SUBSHELL="enforce"  # $() — zero false positives confirmed; blocking
MODE_SCRATCH="enforce"   # scratch files — zero false positives confirmed; blocking
MODE_OR="enforce"        # ||  — zero false positives; promoted 2026-03-24
MODE_SEMICOLON="enforce" # ;   — pwsh/perl exemptions in place; promoted 2026-03-24
MODE_BACKTICK="enforce"  # backticks — zero false positives; promoted 2026-03-24

LOG_DIR="$HOME/.claude/hooks/logs"
LOG_FILE="$LOG_DIR/standing-order-guard.log"

# Ensure log directory exists (needed for observe logging; harmless in enforce-only runs)
mkdir -p "$LOG_DIR"

# --- Telemetry: JSONL event emission ---
# Appends one structured line to the session event log (~0.1ms).
# Session dir resolved from .scratch/.current-session (set by scratch-init.sh).
# If unavailable, silently no-ops (hook must never fail).
_SESSION_DIR=""
_cs_file="$(git rev-parse --show-toplevel 2>/dev/null || echo "")/.scratch/.current-session"
if [ -f "$_cs_file" ]; then
    _SESSION_DIR=$(cat "$_cs_file" 2>/dev/null || true)
fi

emit_hook_event() {
    local event_type="$1" detail_json="$2"
    [ -n "$_SESSION_DIR" ] || return 0
    printf '{"t":"%s","type":"%s","src":"sog","d":%s}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "$event_type" "$detail_json" \
        >> "$_SESSION_DIR/events.jsonl" 2>/dev/null || true
}

# violation() — dispatch based on per-check mode
# $1: message  $2: mode variable value (enforce or observe; defaults to enforce)
# $3: check name (for telemetry)
# In enforce mode: write message to stderr, exit 2 (block)
# In observe mode: append to log file, exit 0 (allow)
violation() {
    local message="$1"
    local mode="${2:-enforce}"
    local check_name="${3:-unknown}"
    if [ "$mode" = "enforce" ]; then
        emit_hook_event "hook_block" "{\"check\":\"$check_name\"}"
        echo "$message" >&2
        exit 2
    else
        emit_hook_event "hook_warn" "{\"check\":\"$check_name\",\"mode\":\"observe\"}"
        printf '%s [WOULD-BLOCK] %s | cmd: %s\n' \
            "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$message" "$COMMAND" \
            >> "$LOG_FILE"
        exit 0
    fi
}

INPUT=$(cat)

# --- Pure-bash JSON field extraction ---
# Same pattern as session-archive.sh. Handles simple top-level string values.
# Uses bash regex (zero external process forks) since this is a hot-path hook.
json_field() {
    local json="$1" key="$2"
    local pattern="\"${key}\"[[:space:]]*:[[:space:]]*\"([^\"]*)\""
    if [[ "$json" =~ $pattern ]]; then
        printf '%s' "${BASH_REMATCH[1]}"
    fi
}

# Extract tool_input.command — it's nested, so we need the command field
# from within tool_input. Since our JSON parser is simple, we can grep for
# the "command" key directly (it appears at the tool_input level).
COMMAND=$(json_field "$INPUT" "command")

# If no command found (shouldn't happen for Bash tool), allow
if [ -z "$COMMAND" ]; then
    exit 0
fi

# --- USO: Scratch files for complex scripting ---
# In JSON, newlines in strings are escaped as \n (literal two-char sequence).
# Count occurrences by measuring string length before/after removing \n sequences.
# This avoids grep exit-code issues with set -euo pipefail when no matches exist.
STRIPPED="${COMMAND//\\n/}"
CMD_LEN=${#COMMAND}
STRIPPED_LEN=${#STRIPPED}
NEWLINE_COUNT=$(( (CMD_LEN - STRIPPED_LEN) / 2 ))
# 5+ lines (4+ newlines) = too complex for inline. Write a temp file instead.
if [ "$NEWLINE_COUNT" -ge 4 ]; then
    LINE_COUNT=$((NEWLINE_COUNT + 1))
    violation "USO: Scratch files --: This command is ~${LINE_COUNT} lines long. Write it to a temp .sh or .ps1 file using the Write tool, execute with Bash, then clean up. USO: never inline long commands in the Bash tool." "$MODE_SCRATCH" "scratch"
fi

# --- USO: Simple Bash commands only ---
# Block compound operators and command substitution that trigger permission prompts.
# Pipelines (|) are explicitly OK per the USO.
# Checked before the first-token allowlist because compound commands like
# `git tag && git push` have `git` as first token and would exit early.
# $() and backtick checks use raw INPUT (not COMMAND) because json_field
# truncates at \" — $(...) inside quoted arguments would be invisible.
case "$COMMAND" in
    *'&&'*) violation "USO: Simple Bash commands only --: Don't use '&&' to chain commands. Make separate Bash tool calls instead. For git in another repo, use 'git -C /path' instead of 'cd /path && git'." "$MODE_AND" "and" ;;
    *'||'*) violation "USO: Simple Bash commands only --: Don't use '||' to chain commands. Make separate Bash tool calls instead." "$MODE_OR" "or" ;;
    *';'*)
        # Exempt ; inside scripting-language arguments: pwsh -Command '...;...' and perl '...;...'
        # The ; is a language-internal statement separator, not a shell command separator.
        # perl: any invocation (perl -ne, -pe, -e, -E, etc.) may contain Perl semicolons.
        case "$COMMAND" in
            pwsh\ *|powershell\ *|perl\ *) ;;
            *) violation "USO: Simple Bash commands only --: Don't use ';' to chain commands. Make separate Bash tool calls instead." "$MODE_SEMICOLON" "semicolon" ;;
        esac
        ;;
esac
case "$INPUT" in
    *'$('*) violation "USO: Simple Bash commands only --: Don't use '\$(...)' command substitution. For commit messages, write to a temp file with Write and use 'git commit -F'. For other values, compute in a prior step." "$MODE_SUBSHELL" "subshell" ;;
    *'`'*)  violation "USO: Simple Bash commands only --: Don't use backtick command substitution. For commit messages, write to a temp file with Write and use 'git commit -F'. For other values, compute in a prior step." "$MODE_BACKTICK" "backtick" ;;
esac

# --- USO: Dedicated tools for file operations ---
# Pattern: command starts with a file-op utility that has a dedicated tool.
# We check the first token of the command (before any arguments).
read -r FIRST_TOKEN _ <<< "$COMMAND"

# Allowlist: commands that look like file ops but are legitimate shell use.
# pwsh wrapping, git operations, npm/node, etc. are always OK.
case "$FIRST_TOKEN" in
    pwsh|powershell|git|npm|node|python*|pip*|cargo|rustup|brew|winget|choco)
        exit 0
        ;;
esac

# --- USO: Simple Bash commands only (glob in destructive operations) ---
# Glob patterns in rm can expand unexpectedly. Write a cleanup script instead.
case "$FIRST_TOKEN" in
    rm)
        case "$COMMAND" in
            *'*'*|*'?'*)
                violation "USO: Simple Bash commands only --: Don't use glob patterns (*, ?) with 'rm'. Write a cleanup script listing the specific files, execute it, then clean up the script." "enforce" "glob-rm"
                ;;
        esac
        ;;
esac

# Check for standalone file-reading commands (should use Read tool)
# Allow in pipelines (cmd | ...) — Read tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    cat)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Read tool instead of 'cat' to read files. The Read tool provides line numbers and handles large files better." "enforce" "cat" ;;
        esac
        ;;
    head)
        case "$COMMAND" in
            *\|*) ;;
            *) violation "USO: Dedicated tools --: Use the Read tool with offset/limit parameters instead of 'head'. Example: Read with limit=20 for the first 20 lines." "enforce" "head" ;;
        esac
        ;;
    tail)
        case "$COMMAND" in
            *\|*) ;;
            *) violation "USO: Dedicated tools --: Use the Read tool with offset parameter instead of 'tail'. Example: Read with offset=100 to start from line 100." "enforce" "tail" ;;
        esac
        ;;
esac

# Check for standalone file-search commands (should use Grep tool)
# Allow in pipelines — Grep tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    grep|rg|egrep|fgrep)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Grep tool instead of '$FIRST_TOKEN' to search file contents. The Grep tool supports regex, file filtering, and multiple output modes." "enforce" "grep" ;;
        esac
        ;;
esac

# Check for file-finding commands (should use Glob tool)
# Allow in pipelines — Glob tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    find)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Glob tool instead of 'find' to locate files. Example: Glob with pattern '**/*.sh' instead of 'find . -name \"*.sh\"'." "enforce" "find" ;;
        esac
        ;;
    ls)
        # ls is borderline -- block when clearly used to list directory contents
        # for exploration (should use Glob or Bash 'ls' for quick checks).
        # Allow: ls is commonly used for quick verification before mkdir, etc.
        # Decision: allow ls, it's a gray area and commonly used in workflows.
        exit 0
        ;;
esac

# Check for file-editing commands (should use Edit tool)
# Allow in pipelines — Edit tool can't pipe output into other commands.
case "$FIRST_TOKEN" in
    sed)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Edit tool instead of 'sed' to modify files. For non-trivial string manipulation, use Perl (USO: Perl for string manipulation)." "enforce" "sed" ;;
        esac
        ;;
    awk)
        case "$COMMAND" in
            *\|*) ;;  # Pipeline — legitimate shell use
            *) violation "USO: Dedicated tools --: Use the Read tool instead of 'awk' to process files. For string manipulation, use Perl (USO: Perl for string manipulation)." "enforce" "awk" ;;
        esac
        ;;
esac

# Check for file-writing patterns (should use Write tool)
# These are harder to detect by first token alone. Check the full first line
# for redirection patterns that indicate file creation.
FIRST_LINE=$(printf '%s' "$COMMAND" | head -1)
case "$FIRST_LINE" in
    echo*\>*|printf*\>*)
        # echo/printf redirecting to a file
        violation "USO: Dedicated tools --: Use the Write tool instead of echo/printf redirection to create files. The Write tool handles encoding and permissions correctly." "enforce" "echo-redirect"
        ;;
esac

# All checks passed — allow the command
emit_hook_event "hook_fire" "{\"result\":\"allow\"}"
exit 0
'@

$hook_scratch = @'
#!/usr/bin/env bash
# scratch-init.sh — Claude Code SessionStart hook
# Creates a unique session scratch directory, logs stale dirs, discovers
# unconsumed handoffs, and registers the session in the harness SQLite DB.
#
# Design decisions:
#   - Silent exit on errors (hook must never break Claude Code)
#   - Logs stale session dirs older than 24h (no auto-delete after 30-file loss)
#   - Writes session dir path to .scratch/.current-session for agents
#   - Uses session_id from CC hook input for deterministic dir names (R1, #53)
#   - Discovers handoffs at .aitools/channel/handoffs/ (R3, #53)
#   - Registers session in harness SQLite DB if harness-db.py is available
#   - SQLite integration is OBSERVE mode (log-only, never blocks)
#   - harness-db.py stderr is NOT suppressed — safety warnings must surface

set -euo pipefail

# --- Pure-bash JSON field extraction (same as harvest-session.sh) ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

# Read hook input from stdin (contains session_id, cwd, etc.)
INPUT=$(cat)
SESSION_ID=$(json_field "$INPUT" "session_id")

# Find project root (hooks run in cwd but we need the git root)
PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
if [ -z "$PROJECT_ROOT" ]; then
    PROJECT_ROOT="$(pwd)"
fi

SCRATCH_DIR="$PROJECT_ROOT/.scratch"

# Ensure .scratch/ exists
mkdir -p "$SCRATCH_DIR"

# --- Log stale session dirs (older than 24h) ---
# These are from crashed or killed sessions where SessionEnd never fired.
# Previously rm -rf'd here, but that destroyed 30 unharvested artifacts
# (session Z1IhGrcgGO, 2026-03-21). Now we leave them for manual cleanup.
if [ -d "$SCRATCH_DIR" ]; then
    stale_count=$(find "$SCRATCH_DIR" -maxdepth 1 -name "session-*" -type d -mmin +1440 2>/dev/null | wc -l | tr -d ' ')
    if [ "$stale_count" -gt 0 ]; then
        printf 'Stale scratch dirs: %d (older than 24h, run cleanup manually)\n' "$stale_count"
    fi
fi

# --- Create fresh session dir ---
# Use session_id for deterministic dir name (fixes .current-session race
# condition for concurrent sessions — M4 AAR P3, verified UA-6).
# Fallback to mktemp if session_id is empty (defensive).
SESSION_PREFIX=""
if [ -n "$SESSION_ID" ]; then
    SESSION_PREFIX=$(printf '%s' "$SESSION_ID" | cut -c1-10)
    SESSION_DIR="$SCRATCH_DIR/session-$SESSION_PREFIX"
    mkdir -p "$SESSION_DIR"
else
    SESSION_DIR=$(mktemp -d "$SCRATCH_DIR/session-XXXXXXXXXX")
fi

# Write the path so agents and the SessionEnd hook can find it
printf '%s' "$SESSION_DIR" > "$SCRATCH_DIR/.current-session"

# --- Discover unconsumed handoffs (R3, issue #53) ---
HANDOFFS_DIR="$PROJECT_ROOT/.aitools/channel/handoffs"
if [ -d "$HANDOFFS_DIR" ]; then
    handoff_count=0
    latest_handoff=""
    for hf in "$HANDOFFS_DIR"/handoff*; do
        [ -f "$hf" ] || continue
        handoff_count=$((handoff_count + 1))
        latest_handoff="$hf"
    done
    if [ "$handoff_count" -gt 0 ]; then
        printf 'Handoff available: %s (%d total in %s)\n' \
            "$(basename "$latest_handoff")" "$handoff_count" "$HANDOFFS_DIR"
    fi
fi

# --- Register session in harness SQLite DB (OBSERVE mode) ---
# This is additive — if harness-db.py is missing or fails, session
# continues normally. SQLite integration never blocks SessionStart.
if [ -n "$SESSION_ID" ]; then
    PYTHON=""
    if command -v python3 > /dev/null 2>&1; then
        PYTHON="python3"
    elif command -v python > /dev/null 2>&1; then
        PYTHON="python"
    fi

    if [ -n "$PYTHON" ]; then
        # Look for harness-db.py in multiple locations
        HELPER=""
        if [ -f "$PROJECT_ROOT/scripts/harness-db.py" ]; then
            HELPER="$PROJECT_ROOT/scripts/harness-db.py"
        elif [ -f "$HOME/repos/aitools/scripts/harness-db.py" ]; then
            HELPER="$HOME/repos/aitools/scripts/harness-db.py"
        fi

        if [ -n "$HELPER" ] && "$PYTHON" -c "import sqlite3" 2>/dev/null; then
            # Initialize harness databases (creates if missing)
            # Let stderr through (warnings visible to Claude), but don't block on failure
            "$PYTHON" "$HELPER" init || true
            # Register this session
            "$PYTHON" "$HELPER" session start --id "$SESSION_ID" || true
            printf 'Harness DB: session %s registered\n' "$SESSION_ID"
        fi
    fi
fi

# SessionStart stdout is added as context for Claude
printf 'Session scratch directory: %s\n' "$SESSION_DIR"
'@

$hook_harvest = @'
#!/usr/bin/env bash
# harvest-session.sh -- Claude Code SessionEnd hook (thin shim)
# Passes the raw hook stdin to ait-harvest.py `harvest`, which classifies the
# session scratch dir, routes handoffs, harvests artifacts to harvesting/,
# updates the manifest, and prunes -- all in stdlib Python (no node).
# Logging lives in ~/.aitools/logs/ait-harvest.log.
#
# Design (plan imperative-gliding-newell.md §4 + §20.2 C3):
#   - Standalone (no aitools-lib); bash-only on all platforms.
#   - Raw stdin -> python (no bash JSON parsing).
#   - Always exit 0 (a hook must never break Claude Code).
#   - Bash-fallback log on no-Python / no-helper / non-zero exit.
#   - DB session-end marking is NOT done here -- harness-db-sessionend.sh owns
#     that (de-dups the overlap the old harvest hook had).
#   - 30-file-loss guards preserved inside the helper (never deletes scratch
#     dirs; marks 'pruned', never unlinks).

set -euo pipefail

INPUT=$(cat)

_fallback_log() {
    local logdir="${HOME:-}/.aitools/logs"
    local logfile="$logdir/harvest-session.log"
    local ts
    ts=$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo "unknown")
    if mkdir -p "$logdir" 2>/dev/null; then
        printf '[%s] [harvest-session] [%s] %s\n' "$ts" "${2:-warn}" "$1" \
            >> "$logfile" 2>/dev/null || true
    fi
}

PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    _fallback_log "no Python on PATH; scratch not harvested" "warn"
    exit 0
fi

PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
HELPER=""
if [ -n "$PROJECT_ROOT" ] && [ -f "$PROJECT_ROOT/scripts/ait-harvest.py" ]; then
    HELPER="$PROJECT_ROOT/scripts/ait-harvest.py"
elif [ -f "$HOME/.claude/hooks/ait-harvest.py" ]; then
    HELPER="$HOME/.claude/hooks/ait-harvest.py"
elif [ -f "$HOME/repos/aitools/scripts/ait-harvest.py" ]; then
    HELPER="$HOME/repos/aitools/scripts/ait-harvest.py"
fi

if [ -z "$HELPER" ]; then
    _fallback_log "ait-harvest.py not found; scratch not harvested" "warn"
    exit 0
fi

if ! printf '%s' "$INPUT" | "$PYTHON" "$HELPER" harvest; then
    _fallback_log "ait-harvest.py harvest exited non-zero" "warn"
fi

exit 0
'@

$hook_shfixup = @'
#!/usr/bin/env bash
# sh-file-fixup.sh — Claude Code PostToolUse hook for Write and Edit
# Auto-fixes .sh files after creation/modification:
#   - CRLF → LF line endings (Write tool on macOS can produce CRLF)
#   - chmod +x on disk (Write tool creates 100644)
#   - git update-index --chmod=+x (if tracked with wrong mode)
#
# Eliminates the recurring manual fixup cycle that interrupts every commit
# involving .sh files. See reference/framework-incident-investigation.md.
#
# Hook contract:
#   - PostToolUse on Write|Edit (runs AFTER the tool completes)
#   - Receives JSON on stdin with tool_input.file_path
#   - Exit 0 always (PostToolUse must never block)
#   - Stderr feedback is shown to Claude

set -euo pipefail

# --- Telemetry: JSONL event emission ---
_SESSION_DIR=""
_cs_file="$(git rev-parse --show-toplevel 2>/dev/null || echo "")/.scratch/.current-session"
if [ -f "$_cs_file" ]; then
    _SESSION_DIR=$(cat "$_cs_file" 2>/dev/null || true)
fi

emit_hook_event() {
    local event_type="$1" detail_json="$2"
    [ -n "$_SESSION_DIR" ] || return 0
    printf '{"t":"%s","type":"%s","src":"fixup","d":%s}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "$event_type" "$detail_json" \
        >> "$_SESSION_DIR/events.jsonl" 2>/dev/null || true
}

# Read JSON from stdin
input=$(cat)

# Extract file_path from tool_input (pure-bash, no jq dependency)
file_path=""
if [[ "$input" =~ \"file_path\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    file_path="${BASH_REMATCH[1]}"
fi

# Only act on .sh files
[ -n "$file_path" ] || exit 0
[[ "$file_path" == *.sh ]] || exit 0
[ -f "$file_path" ] || exit 0

fixed=""

# Fix CRLF → LF
if perl -ne 'exit 1 if /\r/' "$file_path" 2>/dev/null; then
    : # no CRLF found
else
    perl -pi -e 's/\r$//' "$file_path"
    fixed="${fixed}CRLF->LF "
fi

# Fix executable bit on disk
if [ ! -x "$file_path" ]; then
    chmod +x "$file_path"
    fixed="${fixed}+x "
fi

# Fix git index executable bit (if inside a git work tree)
dir=$(dirname "$file_path")
if git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
    mode=$(git -C "$dir" ls-files -s "$file_path" 2>/dev/null | cut -c1-6)
    if [ "$mode" = "100644" ]; then
        git update-index --chmod=+x "$file_path" 2>/dev/null || true
        fixed="${fixed}git+x "
    fi
fi

# Report what was fixed (stderr → shown to Claude as feedback)
if [ -n "$fixed" ]; then
    echo "sh-file-fixup: $(basename "$file_path") — fixed: ${fixed% }" >&2
    emit_hook_event "hook_fire" "{\"file\":\"$(basename "$file_path")\",\"action\":\"${fixed% }\"}"
fi

exit 0
'@

$hook_glossary = @'
#!/usr/bin/env bash
# glossary-skill-guard.sh — Detection layer for governed data access
# Fires on Read/Grep of glossary files, reminds agent to use /glossary skill
# Part of the governed data access framework.
# See reference/framework-governed-data-access.md

set -euo pipefail

# --- Telemetry: JSONL event emission ---
_SESSION_DIR=""
_cs_file="$(git rev-parse --show-toplevel 2>/dev/null || echo "")/.scratch/.current-session"
if [ -f "$_cs_file" ]; then
    _SESSION_DIR=$(cat "$_cs_file" 2>/dev/null || true)
fi

emit_hook_event() {
    local event_type="$1" detail_json="$2"
    [ -n "$_SESSION_DIR" ] || return 0
    printf '{"t":"%s","type":"%s","src":"gsg","d":%s}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "$event_type" "$detail_json" \
        >> "$_SESSION_DIR/events.jsonl" 2>/dev/null || true
}

INPUT=$(cat)
FILE_PATH=$(echo "$INPUT" | perl -ne 'print $1 if /"file_path"\s*:\s*"([^"]*)"/')
PATTERN_PATH=$(echo "$INPUT" | perl -ne 'print $1 if /"path"\s*:\s*"([^"]*)"/')

TARGET="${FILE_PATH:-$PATTERN_PATH}"

case "$TARGET" in
    *glossary.json|*glossary.md)
        emit_hook_event "hook_warn" "{\"target\":\"$(basename "$TARGET")\"}"
        # hookSpecificOutput JSON goes to stdout (structured hook response)
        echo '{"hookSpecificOutput":{"additionalContext":"You are reading glossary files directly. Use /glossary skill instead — it provides the governed process for checking definitions, adding terms, and resolving ambiguities. Reading the file bypasses that process."}}'
        ;;
esac
exit 0
'@

$hook_blockguide = @'
#!/usr/bin/env bash
# block-claude-code-guide.sh — Claude Code PreToolUse hook
# Blocks the built-in claude-code-guide subagent (Haiku model) and
# injects corrective harness context so the agent can proceed with
# accurate information without needing the subagent.
#
# Hook contract:
#   - Fires on PreToolUse for the Agent tool
#   - Receives JSON on stdin (tool_input.subagent_type, etc.)
#   - Exit 0 with no output = allow (all other agent types)
#   - Exit 0 with JSON stdout = deny with corrective context
#
# See: https://github.com/anthropics/claude-code/issues/34730

set -euo pipefail

# --- Telemetry: JSONL event emission ---
_SESSION_DIR=""
_cs_file="$(git rev-parse --show-toplevel 2>/dev/null || echo "")/.scratch/.current-session"
if [ -f "$_cs_file" ]; then
    _SESSION_DIR=$(cat "$_cs_file" 2>/dev/null || true)
fi

emit_hook_event() {
    local event_type="$1" detail_json="$2"
    [ -n "$_SESSION_DIR" ] || return 0
    printf '{"t":"%s","type":"%s","src":"bccg","d":%s}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "$event_type" "$detail_json" \
        >> "$_SESSION_DIR/events.jsonl" 2>/dev/null || true
}

INPUT=$(cat)

# Extract subagent_type from tool_input using bash regex (no jq dependency)
SUBAGENT_TYPE=""
pattern='"subagent_type"[[:space:]]*:[[:space:]]*"([^"]*)"'
if [[ "$INPUT" =~ $pattern ]]; then
    SUBAGENT_TYPE="${BASH_REMATCH[1]}"
fi

if [ "$SUBAGENT_TYPE" = "claude-code-guide" ]; then
    emit_hook_event "hook_block" "{\"blocked\":\"claude-code-guide\"}"
    # Return JSON deny with corrective context.
    # permissionDecisionReason is shown to Claude (not the user) on deny,
    # so it serves as injected harness knowledge.
    cat <<'HOOKJSON'
{
  "hookSpecificOutput": {
    "hookEventName": "PreToolUse",
    "permissionDecision": "deny",
    "permissionDecisionReason": "claude-code-guide subagent is DENIED. It is a Haiku-based built-in that returns inaccurate schema information — it caused a production incident where all hooks were disabled (issue #34730). DO NOT retry this call.\n\nFor Claude Code documentation (hooks, settings, permissions, subagents, MCP), use the chrome-devtools skill to navigate to the .md pages at code.claude.com/docs/en/*.md and read the rendered content. Key pages:\n  - Hooks: code.claude.com/docs/en/hooks.md\n  - Permissions: code.claude.com/docs/en/permissions.md\n  - Sub-agents: code.claude.com/docs/en/sub-agents.md\n  - Settings: code.claude.com/docs/en/settings.md\n  - MCP: code.claude.com/docs/en/mcp.md\n\nQuick reference — hook type schemas:\n  type: \"command\" requires: command (string, shell command to execute)\n  type: \"prompt\"  requires: prompt (string, static LLM prompt text)\n  type: \"http\"    requires: url (string, endpoint URL)\n  type: \"agent\"   requires: prompt (string, task for subagent)\n\nNever mix these — a command-type hook with a prompt field or a prompt-type hook with a command field will break settings.json validation and disable ALL hooks."
  }
}
HOOKJSON
    exit 0
fi

exit 0
'@

$hook_toolops = @'
#!/usr/bin/env bash
# tool-ops-session-audit.sh — SessionEnd hook
# Reads tool-ops.json, runs quick verifications on audit-mode capabilities,
# logs drift and KPIs to tool-ops-audit.jsonl.
#
# Hook contract:
#   - SessionEnd hook, command type
#   - Always exit 0 (advisory — never block session end)
#   - Must handle missing files gracefully
#   - No jq dependency — uses grep/regex for JSON parsing

set -euo pipefail

# Read JSON from stdin (SessionEnd provides session_id, etc.)
input=$(cat)
session_id=""
if [[ "$input" =~ \"session_id\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    session_id="${BASH_REMATCH[1]}"
fi

# Find tool-ops.json
tool_ops=""
if [ -n "${AITOOLS_REPO_PATH:-}" ] && [ -f "$AITOOLS_REPO_PATH/reference/tool-ops.json" ]; then
    tool_ops="$AITOOLS_REPO_PATH/reference/tool-ops.json"
elif [ -f "$HOME/repos/aitools/reference/tool-ops.json" ]; then
    tool_ops="$HOME/repos/aitools/reference/tool-ops.json"
fi
# No tool-ops.json — nothing to audit
[ -n "$tool_ops" ] || exit 0

# Ensure log directory (exit silently if we cannot create it)
log_dir="$HOME/.claude/hooks/logs"
mkdir -p "$log_dir" 2>/dev/null || exit 0  # non-critical — exit clean if mkdir fails
log_file="$log_dir/tool-ops-audit.jsonl"
timestamp=$(date -u +%Y-%m-%dT%H:%M:%SZ)

# --- Contract tests (mock-json-pipe verifications) ---
# Run verification cases from tool-ops.json against deployed hook scripts.
# For each tool with a verifications array, pipe mock input to the target
# hook and check exit code + stdout against expected values.

drift_count=0
test_pass=0
test_fail=0

# Find hook scripts directory
hooks_dir="$HOME/.claude/hooks"

# Verify block-claude-code-guide.sh if deployed
guide_hook="$hooks_dir/block-claude-code-guide.sh"
if [ -f "$guide_hook" ]; then
    # Test 1: Should deny claude-code-guide subagent
    test_input='{"tool_name":"Agent","tool_input":{"subagent_type":"claude-code-guide"}}'
    # Capture output; ignore non-zero exit (should not happen but guard against it)
    test_output=$(echo "$test_input" | bash "$guide_hook" 2>/dev/null) || true  # hook may fail in unusual env — don't abort audit
    if echo "$test_output" | grep -q 'permissionDecision.*deny' 2>/dev/null; then  # grep stderr suppressed — pattern match only
        test_pass=$((test_pass + 1))
    else
        test_fail=$((test_fail + 1))
    fi

    # Test 2: Should allow Explore subagent (no deny output)
    test_input='{"tool_name":"Agent","tool_input":{"subagent_type":"Explore"}}'
    test_output=$(echo "$test_input" | bash "$guide_hook" 2>/dev/null) || true  # same guard as above
    if [ -z "$test_output" ]; then
        # Empty output = allowed (correct behavior)
        test_pass=$((test_pass + 1))
    else
        test_fail=$((test_fail + 1))
    fi
fi

# --- Drift detection: deny rules vs deployed settings ---
settings_file="$HOME/.claude/settings.json"
if [ -f "$settings_file" ] && [ -f "$guide_hook" ]; then
    # Check that block-claude-code-guide.sh is registered in settings.json PreToolUse
    if ! grep -q 'block-claude-code-guide\.sh' "$settings_file" 2>/dev/null; then  # grep stderr suppressed — file may be unreadable
        drift_count=$((drift_count + 1))
    fi
fi

# --- Version dep staleness check ---
# Look for the tool-ops reference doc and count items needing attention
ops_ref=""
if [ -n "${AITOOLS_REPO_PATH:-}" ] && [ -f "$AITOOLS_REPO_PATH/reference/tool-ops-claude-code.md" ]; then
    ops_ref="$AITOOLS_REPO_PATH/reference/tool-ops-claude-code.md"
elif [ -f "$HOME/repos/aitools/reference/tool-ops-claude-code.md" ]; then
    ops_ref="$HOME/repos/aitools/reference/tool-ops-claude-code.md"
fi

stale_deps=0
if [ -n "$ops_ref" ]; then
    # Count lines mentioning CRITICAL that also mention "Last verified" — heuristic for stale items
    # grep -c returns exit 1 on no match; capture in subshell to prevent set -e abort
    stale_deps=$(grep -c 'CRITICAL.*Last verified' "$ops_ref" 2>/dev/null || true)  # stderr suppressed — file may be unreadable
    # Ensure numeric — default to 0 if empty or non-numeric
    if ! [[ "$stale_deps" =~ ^[0-9]+$ ]]; then stale_deps=0; fi
fi

# --- Emit results ---
printf '{"timestamp":"%s","session_id":"%s","test_pass":%d,"test_fail":%d,"drift_count":%d,"stale_deps":%d}\n' \
    "$timestamp" "$session_id" "$test_pass" "$test_fail" "$drift_count" "$stale_deps" \
    >> "$log_file"

exit 0
'@

$hook_dashboard = @'
#!/usr/bin/env bash
# dashboard-serve.sh -- Claude Code SessionStart hook
# Delegates to `aitools dashboard --background` for dashboard lifecycle.
#
# The CLI owns estimation discovery, PID management, port detection, and
# server launch. This hook is a thin dispatcher that extracts project
# root from the hook input and delegates.
#
# Hook contract:
#   - SessionStart hook, command type
#   - stdout is added as context for Claude
#   - Must be fast (<100ms for detection; server starts async)
#   - Must never crash or hang (silent exit on errors)

set -euo pipefail

# Read hook input from stdin (contains session_id, cwd, etc.)
INPUT=$(cat)

# Extract cwd from hook input
cwd=""
if [[ "$INPUT" =~ \"cwd\"[[:space:]]*:[[:space:]]*\"([^\"]+)\" ]]; then
    cwd="${BASH_REMATCH[1]}"
fi

# Find project root
PROJECT_ROOT=""
if [ -n "$cwd" ]; then
    PROJECT_ROOT=$(cd "$cwd" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$cwd")
else
    PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || pwd)
fi

# Find aitools CLI
AITOOLS=""
if command -v aitools >/dev/null 2>&1; then
    AITOOLS="aitools"
elif [ -f "$HOME/.local/bin/aitools" ]; then
    AITOOLS="$HOME/.local/bin/aitools"
fi

if [ -n "$AITOOLS" ]; then
    # Delegate to CLI -- it handles everything
    cd "$PROJECT_ROOT" 2>/dev/null || true
    "$AITOOLS" dashboard --background --project-root "$PROJECT_ROOT" 2>/dev/null || true
else
    # Fallback: direct launch if aitools CLI not installed
    # This preserves functionality during initial setup before first `aitools install`
    PYTHON=""
    if command -v python3 >/dev/null 2>&1; then
        PYTHON="python3"
    elif command -v python >/dev/null 2>&1; then
        PYTHON="python"
    fi
    [ -n "$PYTHON" ] || exit 0

    GENERATOR=""
    if [ -f "$HOME/repos/aitools/scripts/generate-dashboard.py" ]; then
        GENERATOR="$HOME/repos/aitools/scripts/generate-dashboard.py"
    elif [ -f "$PROJECT_ROOT/scripts/generate-dashboard.py" ]; then
        GENERATOR="$PROJECT_ROOT/scripts/generate-dashboard.py"
    fi
    [ -n "$GENERATOR" ] || exit 0

    # Find estimate (simplified -- CLI has full search logic)
    ESTIMATE=""
    if [ -f "$PROJECT_ROOT/.aitools/channel/running-estimate.json" ]; then
        ESTIMATE="$PROJECT_ROOT/.aitools/channel/running-estimate.json"
    fi
    if [ -z "$ESTIMATE" ] && [ -d "$PROJECT_ROOT/.scratch" ]; then
        for dir in "$PROJECT_ROOT"/.scratch/session-*/; do
            [ -d "$dir" ] || continue
            for est in "$dir"/*running-estimate*.json; do
                [ -f "$est" ] || continue
                ESTIMATE="$est"
                break 2
            done
        done
    fi
    [ -n "$ESTIMATE" ] || exit 0

    PORT=8411
    PID_DIR="$PROJECT_ROOT/.aitools"
    mkdir -p "$PID_DIR" 2>/dev/null || PID_DIR="/tmp"
    PID_FILE="$PID_DIR/.dashboard-pid"

    # Check if already running
    if [ -f "$PID_FILE" ]; then
        old_pid=$(cat "$PID_FILE" 2>/dev/null || echo "")
        if [ -n "$old_pid" ] && kill -0 "$old_pid" 2>/dev/null; then
            printf 'Dashboard: http://localhost:%d/\n' "$PORT"
            exit 0
        fi
        rm -f "$PID_FILE"
    fi

    nohup "$PYTHON" "$GENERATOR" --estimate "$ESTIMATE" --serve --port "$PORT" \
        >/dev/null 2>&1 &
    SERVER_PID=$!
    disown "$SERVER_PID" 2>/dev/null || true
    printf '%d' "$SERVER_PID" > "$PID_FILE"
    sleep 0.3
    if kill -0 "$SERVER_PID" 2>/dev/null; then
        printf 'Dashboard: http://localhost:%d/\n' "$PORT"
    else
        rm -f "$PID_FILE"
    fi
fi

exit 0
'@

$hook_hdbstart = @'
#!/usr/bin/env bash
# harness-db-sessionstart.sh -- Claude Code SessionStart hook
# Initializes harness databases and registers the current session.
#
# Design decisions:
#   - Requires Python 3 (sqlite3 stdlib -- no external deps)
#   - Creates harness DB + session DB via harness-db.py helper
#   - Silent exit on missing deps (hook must never break Claude Code)
#   - harness-db.py stderr is NOT suppressed — safety warnings must surface
#   - Cross-platform: Python sqlite3 works on macOS, Windows Git Bash, Linux
#   - Session ID from CC hook input (same pattern as scratch-init.sh)

set -euo pipefail

# --- Pure-bash JSON field extraction (same as scratch-init.sh) ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

# Read hook input from stdin (contains session_id, cwd, etc.)
INPUT=$(cat)
SESSION_ID=$(json_field "$INPUT" "session_id")

# Bail if no session ID (defensive)
if [ -z "$SESSION_ID" ]; then
    exit 0
fi

# Find project root
PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
if [ -z "$PROJECT_ROOT" ]; then
    PROJECT_ROOT="$(pwd)"
fi

# Check for Python 3 (required for harness-db.py)
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    printf 'harness-db: Python 3 not found, skipping DB init\n'
    exit 0
fi

# Verify sqlite3 module is available
if ! "$PYTHON" -c "import sqlite3" 2>/dev/null; then
    printf 'harness-db: Python sqlite3 module not available, skipping DB init\n'
    exit 0
fi

HELPER="$PROJECT_ROOT/scripts/harness-db.py"

# Check helper script exists
if [ ! -f "$HELPER" ]; then
    exit 0
fi

# Initialize harness databases (creates if missing)
# Let stderr through (warnings visible to Claude), but don't block on failure
"$PYTHON" "$HELPER" init || true

# Register this session
"$PYTHON" "$HELPER" session start --id "$SESSION_ID" || true

printf 'Harness DB: session %s registered\n' "$SESSION_ID"
'@

$hook_hdbend = @'
#!/usr/bin/env bash
# harness-db-sessionend.sh -- Claude Code SessionEnd hook
# Marks the current session as complete and exports DB to JSON for
# git carry-forward (Option B: SQLite runtime, JSON archive).
#
# Design decisions:
#   - Requires Python 3 (sqlite3 stdlib -- no external deps)
#   - Exports session DB to .aitools/channel/running-estimate.json (tracked)
#   - Silent exit on missing deps (hook must never break Claude Code)
#   - harness-db.py stderr is NOT suppressed — safety warnings must surface
#   - Cross-platform: Python sqlite3 works on macOS, Windows Git Bash, Linux
#   - Session ID from CC hook input (same pattern as harvest-session.sh)

set -euo pipefail

# --- Pure-bash JSON field extraction (same as harvest-session.sh) ---
json_field() {
    local json="$1" key="$2"
    local val
    val=$(printf '%s' "$json" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | sed 's/.*"'"$key"'"[[:space:]]*:[[:space:]]*"//' \
        | sed 's/"$//')
    printf '%s' "$val"
}

# Read hook input from stdin
INPUT=$(cat)
SESSION_ID=$(json_field "$INPUT" "session_id")

# Bail if no session ID (defensive)
if [ -z "$SESSION_ID" ]; then
    exit 0
fi

# Find project root
CWD=$(json_field "$INPUT" "cwd")
if [ -n "$CWD" ]; then
    PROJECT_ROOT=$(cd "$CWD" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$CWD")
else
    PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "$(pwd)")
fi

# Check for Python 3
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    exit 0
fi

HELPER="$PROJECT_ROOT/scripts/harness-db.py"

# Check helper script exists
if [ ! -f "$HELPER" ]; then
    exit 0
fi

# Mark session as ended
# Let stderr through (warnings visible to Claude), but don't block on failure
"$PYTHON" "$HELPER" session end --id "$SESSION_ID" || true

# Process session events.jsonl into KPI metrics (cold-path telemetry)
# Reads events emitted by enforcement hooks during the session
"$PYTHON" "$HELPER" process-events --session "$SESSION_ID" || true

# Ship KPI events to Datadog (if DD_API_KEY is configured)
"$PYTHON" "$HELPER" ship || true

# Export DB to JSON for git carry-forward
# stderr warnings (e.g. overwrite-smaller-file safety check) must be visible
"$PYTHON" "$HELPER" export --format json --session "$SESSION_ID" || true

printf 'Harness DB: session %s ended, events processed, JSON exported\n' "$SESSION_ID"
'@

$hook_delegguard = @'
#!/usr/bin/env bash
# delegation-duty-guard.sh — Claude Code PreToolUse hook (matcher: Agent)
# Checks subagent delegation prompts for 6 duty elements and injects
# a corrective reminder via stderr when elements are missing.
#
# OBSERVE mode: always allows (exit 0), reminds on gaps.
# Future: promote to enforce after observation period.
#
# Six delegation duty elements:
#   1. Identity (role name, "you are", etc.)
#   2. Rules instruction (CLAUDE.md, .claude/rules)
#   3. Skills instruction (skills, SKILL.md, shared/skills)
#   4. Operational learning (OL, carry forward)
#   5. WRITE_BLOCKED signal
#   6. Access workaround (explicit paths, Glob/Grep, OL-O12)
#
# Hook contract:
#   - PreToolUse hook, matcher: Agent
#   - Receives JSON on stdin (tool_name, tool_input)
#   - Exit 0 = allow (always, OBSERVE mode)
#   - stderr -> shown to agent as feedback
#   - Must be fast (<50ms)
#   - Must never crash or hang
#   - Standalone — cannot source aitools-lib.sh
#
# KPI definitions (logged to harness DB):
#   - delegation.score: duty elements present / 6
#   - delegation.missing: comma-separated list of missing elements
#   - delegation.promptLength: approximate prompt length
#
# Platform: macOS + Linux + Windows Git Bash

set -euo pipefail

# --- Telemetry: JSONL event emission ---
# Appends one structured line to the session event log (~0.1ms).
_SESSION_DIR=""
_cs_file="$(git rev-parse --show-toplevel 2>/dev/null || echo "")/.scratch/.current-session"
if [ -f "$_cs_file" ]; then
    _SESSION_DIR=$(cat "$_cs_file" 2>/dev/null || true)
fi

emit_hook_event() {
    local event_type="$1" detail_json="$2"
    [ -n "$_SESSION_DIR" ] || return 0
    printf '{"t":"%s","type":"%s","src":"ddg","d":%s}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "$event_type" "$detail_json" \
        >> "$_SESSION_DIR/events.jsonl" 2>/dev/null || true
}

# --- Read JSON from stdin ---
input=$(cat)

# --- Extract tool_input content ---
# The Agent tool_input contains the prompt text. We need to search
# within the full input for delegation duty elements.
# The prompt is inside "tool_input" which contains "prompt" or "task".

# --- Check duty elements using Perl (portable, no grep -P) ---
result=$(printf '%s' "$input" | \
    perl -ne '
        my $score = 0;
        my @missing;
        my @present;

        # 1. Identity (role name)
        if (/S[1-9]|you\s+are|your\s+identity|your\s+role|Your\s+identity/i) {
            $score++; push @present, "identity";
        } else {
            push @missing, "identity";
        }

        # 2. Rules instruction
        if (/rules|CLAUDE\.md|\.claude\/rules/i) {
            $score++; push @present, "rules";
        } else {
            push @missing, "rules";
        }

        # 3. Skills instruction
        if (/skills|SKILL\.md|shared\/skills/i) {
            $score++; push @present, "skills";
        } else {
            push @missing, "skills";
        }

        # 4. Operational learning
        if (/operational\s+learning|carry\s+forward|OL-/i) {
            $score++; push @present, "OL";
        } else {
            push @missing, "OL";
        }

        # 5. WRITE_BLOCKED signal
        if (/WRITE_BLOCKED/) {
            $score++; push @present, "WRITE_BLOCKED";
        } else {
            push @missing, "WRITE_BLOCKED";
        }

        # 6. Access workaround
        if (/explicit\s+paths|Glob\/Grep|cross-repo|OL-O12/i) {
            $score++; push @present, "access";
        } else {
            push @missing, "access";
        }

        print "$score\n";
        print join(",", @missing) . "\n";
        print join(",", @present) . "\n";
    ' 2>/dev/null || echo "0
identity,rules,skills,OL,WRITE_BLOCKED,access
")

# Parse result
score=$(printf '%s' "$result" | head -1)
missing=$(printf '%s' "$result" | head -2 | tail -1)

if ! [[ "$score" =~ ^[0-9]+$ ]]; then score=0; fi

# --- Inject reminder if elements are missing ---
if [ "$score" -lt 6 ] && [ -n "$missing" ]; then
    reminder="[delegation-guard] Delegation ${score}/6 duty elements."
    reminder="${reminder} Missing: ${missing}."

    # Build specific guidance for each missing element
    guidance=""
    case ",$missing," in
        *,identity,*)
            guidance="${guidance} Identity: include role name (e.g. 'You are S3-Alpha')."
            ;;
    esac
    case ",$missing," in
        *,rules,*)
            guidance="${guidance} Rules: instruct subagent to read CLAUDE.md and .claude/rules/."
            ;;
    esac
    case ",$missing," in
        *,skills,*)
            guidance="${guidance} Skills: mention available skills or shared/skills/ path."
            ;;
    esac
    case ",$missing," in
        *,OL,*)
            guidance="${guidance} OL: include operational learning items relevant to the task."
            ;;
    esac
    case ",$missing," in
        *,WRITE_BLOCKED,*)
            guidance="${guidance} WRITE_BLOCKED: signal if subagent cannot write to protected files."
            ;;
    esac
    case ",$missing," in
        *,access,*)
            guidance="${guidance} Access: note cross-repo paths and Glob/Grep workarounds (OL-O12)."
            ;;
    esac

    if [ -n "$guidance" ]; then
        reminder="${reminder}${guidance}"
    fi

    printf '%s' "$reminder" >&2

    # --- Emit telemetry event (JSONL, replaces Python subprocess KPI logging) ---
    emit_hook_event "delegation" "{\"score\":$score,\"missing\":\"$missing\"}"
fi

# OBSERVE mode: always allow
exit 0
'@

$hook_ccstop = @'
#!/usr/bin/env bash
# command-channel-stop.sh -- Claude Code Stop hook
# Purpose: Poll the session SQLite DB for pending commander directives and
#   inject them into the agent's context via stderr. This is the "uplink"
#   path of the command channel -- dashboard writes directives to SQLite,
#   this hook reads them at every agent pause.
# Scope: Stop hook only. NOT the directive schema (harness-db.py).
#   NOT the dashboard command interface (session-command-center-v2.py).
# Audience: Claude Code Stop hook system -- fires after every agent response.
#
# Architecture (from command-channel-investigation.md):
#   Layer 1 -- Stop-hook command reader (THIS FILE)
#   Layer 2 -- Command protocol (commander_directives table in session DB)
#   Layer 3 -- Dashboard command interface (session-command-center-v2.py)
#
# Hook contract:
#   - Receives JSON on stdin (session_id, cwd, transcript_summary, etc.)
#   - Exit 0 = no-op (no pending directives)
#   - Exit 2 = block (stderr injected as context, forces agent to address)
#   - Must complete in <50ms (SQLite WAL read)
#   - Must never crash or hang (would break Claude Code)
#
# Priority handling:
#   - flash:    exit 2 (block) -- agent must address immediately
#   - priority: exit 2 (block) -- surfaced with emphasis
#   - normal:   exit 2 (block) -- agent should address when convenient
#   All pending directives are surfaced together. Flash/priority directives
#   get prefixes in the stderr output.
#
# Fallback: also checks commander_feedback table (from dashboard v2)
#   for status='submitted' entries, since both tables serve the same
#   purpose. commander_directives is the canonical table going forward.
#
# Platform: macOS + Linux + Windows Git Bash
# Dependencies: Python 3 with sqlite3 stdlib (same as harness-db hooks)

set -euo pipefail

# --- Read hook input from stdin ---
INPUT=$(cat)

# --- Pure-bash JSON field extraction (same pattern as other hooks) ---
json_field() {
    local json="$1" key="$2"
    local pattern="\"${key}\"[[:space:]]*:[[:space:]]*\"([^\"]*)\""
    if [[ "$json" =~ $pattern ]]; then
        printf '%s' "${BASH_REMATCH[1]}"
    fi
}

SESSION_ID=$(json_field "$INPUT" "session_id")

# Bail if no session ID
if [ -z "$SESSION_ID" ]; then
    exit 0
fi

# --- Find session DB path ---
PROJECT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
if [ -z "$PROJECT_ROOT" ]; then
    exit 0
fi

SESSION_PREFIX="${SESSION_ID:0:10}"
SESSION_DB="$PROJECT_ROOT/.aitools/sessions/${SESSION_PREFIX}.db"

if [ ! -f "$SESSION_DB" ]; then
    exit 0
fi

# --- Check for Python 3 ---
PYTHON=""
if command -v python3 > /dev/null 2>&1; then
    PYTHON="python3"
elif command -v python > /dev/null 2>&1; then
    PYTHON="python"
fi

if [ -z "$PYTHON" ]; then
    exit 0
fi

# --- Poll for pending directives via inline Python ---
# Python writes directive text to stderr (injected into agent context by CC).
# Python prints the directive count to stdout (captured by bash for exit code).
# Single invocation for speed (<50ms with SQLite WAL).
DIRECTIVE_COUNT=$("$PYTHON" - "$SESSION_DB" <<'PYEOF'
import sqlite3
import sys
from datetime import datetime, timezone

db_path = sys.argv[1]

def utcnow():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

try:
    conn = sqlite3.connect(f"file:{db_path}?mode=rw", uri=True, timeout=2.0)
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA busy_timeout=2000")
    conn.row_factory = sqlite3.Row
except Exception:
    print("0")
    sys.exit(0)

pending = []
now = utcnow()

# Check commander_directives table (Layer 2 protocol)
try:
    rows = conn.execute(
        "SELECT directive_id, directive_type, priority, message, target "
        "FROM commander_directives WHERE status = 'pending' ORDER BY created_at"
    ).fetchall()
    for r in rows:
        priority = r["priority"]
        prefix = "[FLASH] " if priority == "flash" else "[PRIORITY] " if priority == "priority" else ""
        dtype = r["directive_type"].upper()
        msg = r["message"]
        target = f" (re: {r['target']})" if r["target"] else ""
        pending.append(f"{prefix}{dtype}{target}: {msg}")
        conn.execute(
            "UPDATE commander_directives SET status = 'acknowledged', acknowledged_at = ? WHERE directive_id = ?",
            (now, r["directive_id"]),
        )
except Exception:
    pass  # table may not exist yet -- that's OK

# Check commander_feedback table (dashboard v2 fallback)
try:
    rows = conn.execute(
        "SELECT feedback_id, feedback_type, message, target "
        "FROM commander_feedback WHERE status = 'submitted' ORDER BY created_at"
    ).fetchall()
    for r in rows:
        ftype = r["feedback_type"].upper()
        msg = r["message"]
        target = f" (re: {r['target']})" if r["target"] else ""
        pending.append(f"{ftype}{target}: {msg}")
        conn.execute(
            "UPDATE commander_feedback SET status = 'acknowledged', acknowledged_at = ? WHERE feedback_id = ?",
            (now, r["feedback_id"]),
        )
except Exception:
    pass  # table may not exist yet -- that's OK

if pending:
    conn.commit()
    print("=== COMMANDER DIRECTIVE(S) ===", file=sys.stderr)
    for p in pending:
        print(f"  {p}", file=sys.stderr)
    print("=== END DIRECTIVES -- Address these before continuing ===", file=sys.stderr)

conn.close()
print(len(pending))
PYEOF
) || DIRECTIVE_COUNT="0"

# Guard: ensure DIRECTIVE_COUNT is a valid number
if ! [[ "$DIRECTIVE_COUNT" =~ ^[0-9]+$ ]]; then
    DIRECTIVE_COUNT="0"
fi

# --- Telemetry: JSONL event emission ---
_SESSION_DIR=""
_cs_file="$PROJECT_ROOT/.scratch/.current-session"
if [ -f "$_cs_file" ]; then
    _SESSION_DIR=$(cat "$_cs_file" 2>/dev/null || true)
fi

if [ -n "$_SESSION_DIR" ] && [ "$DIRECTIVE_COUNT" != "0" ]; then
    printf '{"t":"%s","type":"command_channel","src":"ccs","d":{"count":%s}}\n' \
        "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
        "$DIRECTIVE_COUNT" \
        >> "$_SESSION_DIR/events.jsonl" 2>/dev/null || true
fi

# --- Exit code ---
# If any directives were found and injected via stderr, block (exit 2)
# to force the agent to address them before continuing.
if [ "$DIRECTIVE_COUNT" != "0" ]; then
    exit 2
fi

exit 0
'@

