#
# Provenance: Session f5fa32f9-c (2026-03-29). Intelligence pillar Stop hook.
# Platform: macOS + Linux + Windows Git Bash

set -euo pipefail

# --- Read hook input from stdin (must capture before pipe) ---
INPUT=$(cat)

